<?php
require 'config/db.php';require 'includes/functions.php';verify_csrf();
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(post('action')==='add'){
  $asset=(int)post('asset_id');$desc=post('description');$vendor=post('vendor');$cost=(float)post('cost','0');
  if($asset&&$desc!==''){$pdo->beginTransaction();try{$q=$pdo->prepare("INSERT INTO maintenance_records(asset_id,description,vendor,cost,status) VALUES(?,?,?,?,'Open')");$q->execute([$asset,$desc,$vendor,$cost]);$q=$pdo->prepare("UPDATE assets SET status='Under Maintenance',assigned_to=NULL WHERE id=?");$q->execute([$asset]);$pdo->commit();flash('Maintenance record created.');}catch(Throwable $e){$pdo->rollBack();throw $e;}}redirect('maintenance.php');
 }
 if(post('action')==='resolve'){$id=(int)post('id');$pdo->beginTransaction();try{$q=$pdo->prepare("UPDATE maintenance_records SET status='Resolved',resolved_at=NOW() WHERE id=? AND status='Open'");$q->execute([$id]);$q=$pdo->prepare("UPDATE assets SET status='Available' WHERE id=(SELECT asset_id FROM maintenance_records WHERE id=?)");$q->execute([$id]);$pdo->commit();flash('Maintenance marked resolved; asset set to Available.');}catch(Throwable $e){$pdo->rollBack();throw $e;}redirect('maintenance.php');}
}
$assets=$pdo->query("SELECT id,asset_tag,name FROM assets WHERE status!='Retired' ORDER BY asset_tag")->fetchAll();
$rows=$pdo->query("SELECT m.*,a.asset_tag,a.name asset_name FROM maintenance_records m JOIN assets a ON a.id=m.asset_id ORDER BY m.id DESC")->fetchAll();$pageTitle='Maintenance';require 'includes/header.php';?>
<h1>Maintenance</h1><section class="panel"><h2>Log maintenance</h2><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="add"><div class="formgrid"><label>Asset<select required name="asset_id"><?php foreach($assets as $a):?><option value="<?=$a['id']?>"><?=e($a['asset_tag'].' — '.$a['name'])?></option><?php endforeach;?></select></label><label>Description<input required name="description"></label><label>Vendor<input name="vendor"></label><label>Cost<input type="number" step="0.01" min="0" name="cost" value="0"></label></div><button>Create record</button></form></section>
<section class="panel"><h2>Maintenance history</h2><table><tr><th>Asset</th><th>Description</th><th>Vendor</th><th>Cost</th><th>Status</th><th>Action</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['asset_tag'].' — '.$r['asset_name'])?></td><td><?=e($r['description'])?></td><td><?=e($r['vendor'])?></td><td><?=number_format((float)$r['cost'],2)?></td><td><?=e($r['status'])?></td><td><?php if($r['status']==='Open'):?><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="resolve"><input type="hidden" name="id" value="<?=$r['id']?>"><button>Resolve</button></form><?php endif;?></td></tr><?php endforeach;?></table></section><?php require 'includes/footer.php';?>
